# Generated by manage.py generate_test_cases.
from functools import partial
from unittest.mock import patch

from django.apps import apps
from django.contrib.contenttypes.models import ContentType

from bloomerp.models.application_field import ApplicationField
from bloomerp.models.definition import (
    BloomerpModelConfig,
    DetailViewSettings,
    FieldLayout,
    LayoutItem,
    LayoutRow,
    get_model_config,
)
from bloomerp.models.users.user_object_layout_preference import (
    UserObjectLayoutPreference,
)
from bloomerp.services.preference_services import PreferenceManager
from bloomerp.tests.base import (
    BaseBloomerpTestCaseWithModels,
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)


class TestUserObjectLayoutPreferenceModel(
    BloomerpModelTestCase,
    BaseBloomerpTestCaseWithModels,
):
    model = UserObjectLayoutPreference

    def get_test_scenarios(self) -> list[ModelScenario[UserObjectLayoutPreference]]:
        """Cover grouped built-in layouts alongside multiple-layout selection."""
        return [
            *[
                ModelScenario(
                    name=f"{model_name} materializes complete sections and preserves customization",
                    create_operation=partial(self.get_builtin_layout, model_name),
                    create_validators=self.builtin_layout_is_materialized,
                )
                for model_name in (
                    "DocumentTemplateStyling", "SqlQuery", "AIAgentAccess", "MCPIntegration",
                    "CalendarBooking", "CalendarBookingSubmission", "CalendarEventParticipant",
                )
            ],
            ModelScenario(
                name="Configured object layouts are all materialized and default selected",
                description=(
                    "UC: A model declares multiple detail layouts.\n"
                    "Expected Result: Every layout becomes a user preference and the declared default is selected."
                ),
                create_operation=self.create_configured_preferences,
                create_validators=self.configured_preferences_are_materialized,
            )
        ]

    def get_builtin_layout(self, model_name: str) -> UserObjectLayoutPreference:
        """Open built-in details through the ordinary preference lifecycle."""
        content_type = ContentType.objects.get_for_model(
            apps.get_model("bloomerp", model_name)
        )
        selected = PreferenceManager(self.admin_user).get_or_create_selected(
            UserObjectLayoutPreference, {"content_type_id": content_type.pk}
        )
        self.assertIsInstance(selected, UserObjectLayoutPreference)
        return selected

    def builtin_layout_is_materialized(self, selected: UserObjectLayoutPreference) -> bool:
        """Require every configured item to resolve and retain a customized section."""
        model = selected.content_type.model_class()
        layout = get_model_config(model).detail_view_settings.layouts[0]
        expected_rows = [
            {
                "title": row.title,
                "columns": row.columns,
                "items": [
                    {
                        **item.model_dump(),
                        "id": ApplicationField.get_by_field(model, item.id).pk,
                    }
                    for item in row.items
                ],
            }
            for row in layout.rows
        ]
        self.assertTrue(selected.selected)
        self.assertEqual(selected.layout["rows"], expected_rows)
        self.assertEqual(self.get_builtin_layout(model.__name__).pk, selected.pk)
        selected.name = "My details"
        selected.layout["rows"] = [expected_rows[0]]
        selected.layout["rows"][0]["title"] = "My section"
        selected.save()
        reopened = self.get_builtin_layout(model.__name__)
        self.assertEqual(reopened.pk, selected.pk)
        self.assertEqual(reopened.name, "My details")
        self.assertEqual(reopened.layout, selected.layout)
        self.assertEqual(
            UserObjectLayoutPreference.objects.filter(
                user=self.admin_user, content_type=selected.content_type
            ).count(),
            1,
        )
        return True

    def create_configured_preferences(self):
        self.content_type = ContentType.objects.get_for_model(self.CustomerModel)
        settings = DetailViewSettings(
            layouts=[
                FieldLayout(
                    name="Compact",
                    is_default=False,
                    rows=[LayoutRow(columns=1, items=[LayoutItem(id="first_name")])],
                ),
                FieldLayout(
                    name="Detailed",
                    rows=[LayoutRow(columns=1, items=[LayoutItem(id="last_name")])],
                ),
            ]
        )
        with patch.object(
            self.CustomerModel,
            "bloomerp_config",
            BloomerpModelConfig(detail_view_settings=settings),
            create=True,
        ):
            return UserObjectLayoutPreference.create_default_for_user(
                self.admin_user,
                content_type_id=self.content_type.pk,
            )

    def configured_preferences_are_materialized(self, selected):
        preferences = list(
            UserObjectLayoutPreference.objects.filter(
                user=self.admin_user,
                content_type=self.content_type,
            ).order_by("pk")
        )
        first_name = ApplicationField.get_by_field(self.CustomerModel, "first_name")
        last_name = ApplicationField.get_by_field(self.CustomerModel, "last_name")
        return (
            [preference.name for preference in preferences] == ["Compact", "Detailed"]
            and not preferences[0].selected
            and preferences[1].selected
            and selected == preferences[1]
            and preferences[0].layout["rows"][0]["items"][0]["id"] == first_name.pk
            and preferences[1].layout["rows"][0]["items"][0]["id"] == last_name.pk
        )
